import { $, $$, icon, escape, button } from './dom.js';
import { useStore } from './core/store.js';
import { getEngine } from './core/engine.js';
import { toast } from './core/toast.js';
import { allEffects, getEffect } from './core/effects/registry.js';
import { addEffect, setParams, chainOf } from './features/effects/chain.js';
import { PROCESSES, getProcess, runProcess, learnNoiseFromSelection, useJob } from './features/effects/processes.js';
import { runExport, DEFAULT_SETTINGS } from './features/io/export/pipeline.js';
import { download } from './features/io/state.js';
import { useRecSettings, startRecording } from './features/io/record.js';
import { getAutosaveInfo, restoreAutosave } from './features/io/autosave.js';
import * as music from './media.js';
const dialog=$('#modal'),inner=$('.modal-inner',dialog);
let onClose=null;
export function closeModal(){dialog.close();onClose?.();onClose=null}
export function showModal(title,body,afterClose=null){onClose?.();onClose=afterClose;inner.innerHTML=`<div class="modal-head"><h2>${escape(title)}</h2><button class="icon" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!dialog.open)dialog.showModal()}
dialog.addEventListener('click',e=>{if(e.target===dialog)closeModal()});dialog.addEventListener('cancel',()=>{onClose?.();onClose=null});
export async function welcome(actions){
 const info=await getAutosaveInfo();
 showModal('',`<div class="io-welcome welcome"><div class="io-blobs" aria-hidden="true"><span class="io-blob b1"></span><span class="io-blob b2"></span><span class="io-blob b3"></span></div><div class="io-hero"><div class="io-logo"><span></span><span></span><span></span><span></span></div><h1>Welcome to HitStudio</h1><span class="io-domain">hitstudio.org</span><p class="io-promise">Make music. Feel it.</p><p>Your space to create, mix and get lost in sound.</p><p class="io-tagline">Runs in your browser. Nothing is uploaded.</p></div><div class="io-cards">${info?`<button class="io-card io-card-wide" data-action="restore-project"><span class="io-card-icon">${icon('previous')}</span><b>Continue where you left off</b><small>“${escape(info.name)}” · ${info.tracks} tracks</small></button>`:''}${[
 ['record','mic','Record your voice','Talk, sing or play – straight from your microphone.'],
 ['import-project','folder','Import audio','Drop in songs, voice memos or even video files.'],
 ['welcome-create','create','Make a beat','Tap out drums and melodies with the step sequencer.'],
 ['welcome-dj','dj','DJ two songs','Two decks, a crossfader and automatic tempo matching.'],
 ['demo','visualize','Try the demo song','A ready-made 4-track song to play with.'],
 ['welcome-listen','headphones','Listen & visualize','Open your song list and watch the music move.']
 ].map(([action,glyph,title,sub])=>`<button class="io-card" data-action="${action}"><span class="io-card-icon">${icon(glyph)}</span><b>${title}</b><small>${sub}</small></button>`).join('')}</div><div class="io-welcome-foot"><label><input id="welcome-dismiss" type="checkbox" ${localStorage.getItem('bloom.welcome.dismissed')==='1'?'checked':''}/> Don’t show this when I start</label><button class="io-link" data-action="close-modal">Start with an empty project →</button></div></div>`);
 $('#welcome-dismiss')?.addEventListener('change',e=>localStorage.setItem('bloom.welcome.dismissed',e.target.checked?'1':'0'));
}

export function showSongMenu(id){const item=music.songs.find(s=>s.id===id);if(!item)return;showModal(item.title,`<p class="tip">${escape(item.artist)}</p><div class="stack"><button id="song-edit">${icon('edit')} Add to timeline</button><div class="row"><button id="song-up">Move up</button><button id="song-down">Move down</button><button class="danger" id="song-remove">Remove from song list</button></div></div>`);$('#song-edit').onclick=async()=>{await music.songToProject(id);closeModal()};$('#song-up').onclick=()=>music.moveSong(id,-1);$('#song-down').onclick=()=>music.moveSong(id,1);$('#song-remove').onclick=()=>{void music.removeSong(id);closeModal()}}
export function showEffects(target){showModal('Add an effect',`<p class="tip">Effects run in real time and are saved with the project.</p><div class="effect-list">${allEffects().map(f=>`<button data-type="${f.type}" title="${escape(f.description)}">${escape(f.name)} <small>${escape(f.category||'')}</small></button>`).join('')}</div>`);$$('[data-type]',inner).forEach(b=>b.onclick=()=>{const id=addEffect(target,b.dataset.type);if(id)showEffectParams(target,id)})}
function paramFields(params,values){return params.map(p=>`<label>${escape(p.label)} ${p.unit?`(${escape(p.unit)})`:''}${p.options?`<select data-param="${p.key}">${p.options.map((v,i)=>`<option value="${i}" ${values[p.key]===i?'selected':''}>${escape(v)}</option>`).join('')}</select>`:p.toggle?`<input data-param="${p.key}" type="checkbox" ${values[p.key]>=.5?'checked':''}/>`:`<input data-param="${p.key}" type="range" min="${p.min}" max="${p.max}" step="${p.step??.01}" value="${values[p.key]??p.default}" aria-label="${escape(p.label)}"/><output>${values[p.key]??p.default}</output>`}<small>${escape(p.hint||'')}</small></label>`).join('')}
export function showEffectParams(target,id){const fx=chainOf(useStore.getState().project,target)?.find(f=>f.id===id);if(!fx)return;const def=getEffect(fx.type);showModal(def.name,`<p class="tip">${escape(def.description)}</p><div class="row" style="margin-bottom:20px">${Object.keys(def.presets||{}).map(name=>`<button data-fx-preset="${escape(name)}">${escape(name)}</button>`).join('')}</div><div class="fx-controls">${paramFields(def.params,fx.params)}</div>`);$$('[data-param]',inner).forEach(input=>input.addEventListener('input',()=>{const value=input.type==='checkbox'?(input.checked?1:0):Number(input.value);setParams(target,id,{[input.dataset.param]:value},`native-fx:${id}:${input.dataset.param}`);const out=input.parentElement.querySelector('output');if(out)out.textContent=value}));$$('[data-fx-preset]',inner).forEach(b=>b.onclick=()=>{setParams(target,id,def.presets[b.dataset.fxPreset]);showEffectParams(target,id)})}
export function showProcesses(){showModal('Process selected audio',`<p class="tip">Select one or more timeline clips first. Processing creates a new source and can be undone.</p><div class="effect-list">${PROCESSES.map(p=>`<button data-process="${p.id}" title="${escape(p.description)}">${escape(p.label)}</button>`).join('')}</div>`);$$('[data-process]',inner).forEach(b=>b.onclick=()=>showProcess(b.dataset.process))}
export function showProcess(id){const def=getProcess(id);if(!def)return;const params=Object.fromEntries((def.params||[]).map(p=>[p.key,p.default]));showModal(def.label,`<p class="tip">${escape(def.description)}</p>${id==='noiseReduce'?'<button id="learn-noise">Learn noise from selected range</button>':''}<div class="fx-controls">${paramFields(def.params||[],params)}</div><progress class="progress" id="process-progress" max="1" value="0"></progress><div class="row" style="margin-top:20px"><button class="primary" id="apply-process">Apply to selection</button></div>`);$('#learn-noise')?.addEventListener('click',()=>{toast(learnNoiseFromSelection()?'Noise profile captured.':'Select a range containing only background noise.')} );$$('[data-param]',inner).forEach(input=>input.addEventListener('input',()=>{params[input.dataset.param]=input.type==='checkbox'?(input.checked?1:0):Number(input.value);const out=input.parentElement.querySelector('output');if(out)out.textContent=params[input.dataset.param]}));const unsubscribe=useJob.subscribe(s=>{const progress=$('#process-progress');if(progress)progress.value=s.progress});onClose=unsubscribe;$('#apply-process').onclick=async()=>{const b=$('#apply-process');b.disabled=true;try{if(await runProcess(id,params))closeModal()}catch(error){toast(String(error))}finally{b.disabled=false}}}
export function showExport(preset=null){showModal('Export your audio',`<p class="tip">Exports the arrangement with its track processing. Listening-library songs must be added to the timeline first.</p><form id="export-form" class="stack"><div class="export-grid"><label class="field">Format<select name="format">${['mp3','wav','flac','aiff','opus'].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="field">Content<select name="target"><option value="song">Whole arrangement</option><option value="selection">Selected time range</option><option value="loop">Loop range</option><option value="stems">Separate tracks (ZIP)</option></select></label><label class="field">Title<input name="title" value="${escape(useStore.getState().project.name)}"/></label><label class="field">Artist<input name="artist" /></label><label class="field">Loudness<select name="loudness"><option value="off">Keep original levels</option><option value="streaming">Streaming</option><option value="podcast">Podcast</option></select></label><label class="field">Sample rate<select name="sampleRate"><option value="44100">44.1 kHz</option><option value="48000">48 kHz</option></select></label></div><progress class="progress" id="export-progress" value="0" max="1"></progress><p class="tip" id="export-status"></p><div class="row"><button type="submit" class="primary">${icon('download')} Export audio</button><button type="button" id="cancel-export">Cancel</button></div></form>`);if(preset){for(const [key,value]of Object.entries(preset)){const field=$(`[name="${key}"]`,inner);if(field)field.value=value}}const ctl={cancelled:false,onProgress(p){const progress=$('#export-progress');if(progress)progress.value=p}};onClose=()=>{ctl.cancelled=true};$('#cancel-export').onclick=()=>{ctl.cancelled=true;closeModal()};$('#export-form').onsubmit=async e=>{e.preventDefault();music.stopAll();const form=new FormData(e.target),settings={...DEFAULT_SETTINGS,...Object.fromEntries(form),sampleRate:Number(form.get('sampleRate'))};const b=$('button[type=submit]',e.target);b.disabled=true;try{const result=await runExport(settings,ctl);download(result.blob,result.filename);$('#export-status').textContent='Export saved to your downloads.';toast('Audio exported.')}catch(error){if(!ctl.cancelled){$('#export-status').textContent=String(error);toast(String(error))}}finally{b.disabled=false}}}
export function showRecord(){const s=useRecSettings.getState();showModal('Record a take',`<p class="tip">Your microphone is requested only when you press Start recording.</p><form id="record-form" class="stack"><label><input name="clean" type="checkbox" ${s.clean?'checked':''}/> Browser voice cleanup</label><label><input name="monitor" type="checkbox" ${s.monitor?'checked':''}/> Monitor microphone (use headphones)</label><label><input name="countIn" type="checkbox" ${s.countIn?'checked':''}/> Count in before recording</label><label class="field">Mode<select name="mode"><option value="voice" ${s.mode==='voice'?'selected':''}>Voice (mono)</option><option value="music" ${s.mode==='music'?'selected':''}>Music (stereo when available)</option></select></label><button class="primary" type="submit">${icon('mic')} Start recording</button></form>`);$('#record-form').onsubmit=async e=>{e.preventDefault();music.stopAll();await music.setSource('studio');const f=e.target;useRecSettings.getState().patch({clean:f.clean.checked,monitor:f.monitor.checked,countIn:f.countIn.checked,mode:f.mode.value});closeModal();await startRecording()}}
export { closeModal as close };
